#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> marks;
    size_t last = marks.capacity();
    for (int i = 1; i <= 17; i++) {
        marks.push_back(i);
        if (marks.capacity() != last) {
            cout << "size " << marks.size() << " -> capacity " << marks.capacity() << "\n";
            last = marks.capacity();
        }
    }
    vector<int> planned;
    planned.reserve(17);                      // one allocation up front
    for (int i = 1; i <= 17; i++) planned.push_back(i);
    cout << "with reserve(17): capacity " << planned.capacity() << "\n";
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

void print(const char* label, const vector<int>& v) {
    cout << label;
    for (int x : v) cout << " " << x;
    cout << "\n";
}

int main() {
    vector<int> wrong = {70, -1, -1, 85, -1, 90};          // -1 means absent
    for (size_t i = 0; i < wrong.size(); i++)
        if (wrong[i] == -1) wrong.erase(wrong.begin() + i);  // skips the element that slides in
    print("index loop:", wrong);

    vector<int> right = {70, -1, -1, 85, -1, 90};
    right.erase(remove(right.begin(), right.end(), -1), right.end());
    print("erase-remove:", right);
    return 0;
}

