#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

void removeAll(vector<int>& v, int x) {
    v.erase(remove(v.begin(), v.end(), x), v.end());
}

int main() {
    int n, x;
    if (!(cin >> n >> x)) return 0;
    vector<int> v(n);
    for (int& e : v) cin >> e;
    removeAll(v, x);
    if (v.empty()) cout << "empty\n";
    for (size_t i = 0; i < v.size(); i++) cout << v[i] << (i + 1 < v.size() ? ' ' : '\n');
    return 0;
}
